-- village.csv: 19708 rows; SHA256 f7d5572ef081c18cac520db568620cbcd3e7f96c6e705d75d71d85452d489685
-- Execute the COMPLETE file in MySQL Workbench on a fresh connection.
-- Target: metis.villages. Matching IDs are updated; other existing rows are retained.
-- Timestamps interpreted in the application's Asia/Kolkata timezone (+05:30).
-- Data is embedded: no LOCAL INFILE or server-side CSV file is required.
USE `metis`;
SET @villages_previous_sql_mode = @@SESSION.sql_mode;
SET @villages_previous_time_zone = @@SESSION.time_zone;
SET SESSION sql_mode = CONCAT_WS(',', NULLIF(@@SESSION.sql_mode, ''), 'STRICT_ALL_TABLES');
SET SESSION time_zone = '+05:30';
DROP TEMPORARY TABLE IF EXISTS `_villages_csv_stage_20261103`;
CREATE TEMPORARY TABLE `_villages_csv_stage_20261103` LIKE `metis`.`villages`;








































































































































































































-- No target-table writes occur until the entire staged file is validated.
DROP PROCEDURE IF EXISTS `metis`.`_import_villages_csv_f7d5572ef0`;
DELIMITER $$
CREATE PROCEDURE `metis`.`_import_villages_csv_f7d5572ef0`()
SQL SECURITY INVOKER
BEGIN
    DECLARE matched_rows BIGINT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET SESSION sql_mode = @villages_previous_sql_mode;
        SET SESSION time_zone = @villages_previous_time_zone;
        RESIGNAL;
    END;
    IF (SELECT COUNT(*) FROM `_villages_csv_stage_20261103`) <> 19708 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Incomplete CSV staging. No villages imported. Execute the complete file.';
    END IF;
    START TRANSACTION;
    UPDATE `metis`.`villages` v
    JOIN `_villages_csv_stage_20261103` s ON s.id = v.id
    SET v.`village_name` = s.`village_name`,
        v.`normalized_name` = s.`normalized_name`,
        v.`pincode` = s.`pincode`,
        v.`post_so_name` = s.`post_so_name`,
        v.`taluka_name` = s.`taluka_name`,
        v.`district_name` = s.`district_name`,
        v.`state_name` = s.`state_name`,
        v.`office_id` = s.`office_id`,
        v.`office_type_code` = s.`office_type_code`,
        v.`delivery_office_flag` = s.`delivery_office_flag`,
        v.`is_rolled_out` = s.`is_rolled_out`,
        v.`created_at` = s.`created_at`,
        v.`updated_at` = s.`updated_at`,
        v.`deleted_at` = s.`deleted_at`;
    SELECT s.`id`, s.`village_name`, s.`normalized_name`, s.`pincode`, s.`post_so_name`, s.`taluka_name`, s.`district_name`, s.`state_name`, s.`office_id`, s.`office_type_code`, s.`delivery_office_flag`, s.`is_rolled_out`, s.`created_at`, s.`updated_at`, s.`deleted_at`
    FROM `_villages_csv_stage_20261103` s
    LEFT JOIN `metis`.`villages` v ON v.id = s.id
    WHERE v.id IS NULL;
    SELECT COUNT(*) INTO matched_rows
    FROM `metis`.`villages` v JOIN `_villages_csv_stage_20261103` s ON v.id = s.id
    WHERE v.`id` <=> s.`id` AND v.`village_name` <=> s.`village_name` AND v.`normalized_name` <=> s.`normalized_name` AND v.`pincode` <=> s.`pincode` AND v.`post_so_name` <=> s.`post_so_name` AND v.`taluka_name` <=> s.`taluka_name` AND v.`district_name` <=> s.`district_name` AND v.`state_name` <=> s.`state_name` AND v.`office_id` <=> s.`office_id` AND v.`office_type_code` <=> s.`office_type_code` AND v.`delivery_office_flag` <=> s.`delivery_office_flag` AND v.`is_rolled_out` <=> s.`is_rolled_out` AND v.`created_at` <=> s.`created_at` AND v.`updated_at` <=> s.`updated_at` AND v.`deleted_at` <=> s.`deleted_at`;
    IF matched_rows <> 19708 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Village verification failed. All target changes rolled back.';
    END IF;
    COMMIT;
    SELECT 'SUCCESS' AS import_status, matched_rows AS csv_rows_verified,
        (SELECT COUNT(*) FROM `metis`.`villages`) AS total_table_rows;
END$$
DELIMITER ;
CALL `metis`.`_import_villages_csv_f7d5572ef0`();
DROP PROCEDURE `metis`.`_import_villages_csv_f7d5572ef0`;
DROP TEMPORARY TABLE `_villages_csv_stage_20261103`;
SET SESSION sql_mode = @villages_previous_sql_mode;
SET SESSION time_zone = @villages_previous_time_zone;
